import { util, runtime } from '@aws-appsync/utils';

// Looks up which VP ids were shared with the caller, via the
// VirtualParticipantShareIndex mirror table kept in sync by
// share/unshareVirtualParticipant. Admins don't need this - skip straight
// to the next pipeline step.
export function request(ctx) {
  if (ctx.stash.isAdmin) {
    return runtime.earlyReturn({});
  }
  return {
    operation: 'GetItem',
    key: util.dynamodb.toMapValues({ PK: `u#${ctx.identity.username}` }),
  };
}

export function response(ctx) {
  const item = ctx.result;
  ctx.stash.sharedVpIds = item && item.VpIds ? item.VpIds : [];
  return {};
}
